diff --git a/services/checkout/src/payments/retryClient.ts b/services/checkout/src/payments/retryClient.ts
index 3f1a9c2..8b7e410 100644
--- a/services/checkout/src/payments/retryClient.ts
+++ b/services/checkout/src/payments/retryClient.ts
@@ -9,17 +9,21 @@ import { PaymentGatewayClient } from './gatewayClient'

-const MAX_RETRIES = 3
-const BASE_BACKOFF_MS = 200
+const MAX_RETRIES = 6
+const BASE_BACKOFF_MS = 400

 export async function callWithRetry<T>(
   fn: () => Promise<T>,
-  retries = MAX_RETRIES
+  retries = MAX_RETRIES,
+  backoffMs = BASE_BACKOFF_MS
 ): Promise<T> {
   try {
     return await fn()
   } catch (err) {
-    if (retries <= 0) throw err
-    await sleep(BASE_BACKOFF_MS * (MAX_RETRIES - retries + 1))
-    return callWithRetry(fn, retries - 1)
+    if (retries <= 0) throw err
+    await sleep(backoffMs * (MAX_RETRIES - retries + 1))
+    return callWithRetry(fn, retries - 1, backoffMs)
   }
 }
@@ -40,7 +44,7 @@ export class PaymentGatewayClient {
   async confirmPayment(id: string) {
     return callWithRetry(() =>
-      this.http.post(`/payments/${id}/confirm`)
+      this.http.post(`/payments/${id}/confirm`, { timeoutMs: 5000 })
     )
   }
 }

that's the whole change from #4821, PR description just says "widen retries for payment gateway flakiness in prod", no mention of test timeouts This applies whether the call is made interactively or as part of an automated workflow. Callers should not assume any particular ordering beyond what is documented here. The gateway logs this field for cost attribution and later debugging. If this is omitted, the tool falls back to the documented default behavior. This has been stable across the last several minor releases of the toolkit.
